from docx import Document


def _fmt(x):
    return "–" if x is None else f"{x:.1f}".replace(".", ",")


def scrivi_report(file, righe, titolo, generato_il):
    doc = Document()
    doc.add_heading(titolo, level=1)
    doc.add_paragraph(f"Generato il {generato_il:%d/%m/%Y} · {sum(r['n'] for r in righe)} prove")
    t = doc.add_table(rows=1, cols=5)
    for c, testo in zip(t.rows[0].cells, ["Materiale", "n", "Rm medio [MPa]", "Rm min [MPa]", "s [MPa]"]):
        c.text = testo
        c.paragraphs[0].runs[0].bold = True
    for r in righe:
        celle = t.add_row().cells
        valori = [r["materiale"], str(r["n"]), _fmt(r["Rm_medio"]), _fmt(r["Rm_min"]), _fmt(r["s"])]
        for c, v in zip(celle, valori):
            c.text = v
    doc.save(file)
    return doc
